"""Small responsive projection of supervised coding authority and evidence."""
SUPERVISED_HTML = r'''<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>AMODEX · Luau supervisionado</title><style>
:root{color-scheme:dark;font:16px system-ui,-apple-system,sans-serif;background:#0c1018;color:#eef2fc}*{box-sizing:border-box}
body{margin:0;padding:max(16px,env(safe-area-inset-top)) max(16px,env(safe-area-inset-right)) max(24px,env(safe-area-inset-bottom)) max(16px,env(safe-area-inset-left))}
main{max-width:1000px;margin:auto}a{color:#a2c8ff;display:inline-flex;min-height:44px;align-items:center}h1{font-size:1.65rem}h2{font-size:1.1rem}p{line-height:1.5;color:#bcc9df}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{padding:18px;border:1px solid #36445c;border-radius:16px;background:#141d2b;min-width:0;margin-bottom:16px}
label{display:block;margin:14px 0 7px}select,button{font:inherit;min-height:48px;width:100%;border-radius:10px;padding:10px;border:1px solid #536584;background:#1c2a40;color:inherit}
button{cursor:pointer;background:#214b86;margin-top:12px;font-weight:650}button:disabled{opacity:.5;cursor:default}input[type=checkbox]{width:24px;height:24px;vertical-align:middle;margin-right:8px}
pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:.85rem;line-height:1.5;background:#0b121d;padding:12px;border-radius:8px;max-height:360px;overflow:auto}
small{display:block;overflow-wrap:anywhere;line-height:1.5;color:#c2cee2}.status{font-weight:750;color:#a9d4ff;overflow-wrap:anywhere}#error{color:#ffc7ad;overflow-wrap:anywhere}ul{padding-left:20px;line-height:1.8}summary{min-height:44px;cursor:pointer}section[hidden]{display:none}
@media(max-width:700px){.grid{grid-template-columns:1fr}body{padding-left:12px;padding-right:12px}.card{padding:14px}h1{font-size:1.45rem}}
</style></head><body><main><a href="/">← Workspace</a><h1>Luau supervisionado</h1>
<p>Selecione um rascunho pronto no chat. Revise o arquivo e autorize uma tentativa curta de edição com IA gratuita. O resultado fica salvo aqui como artefato; a experiência Roblox não é alterada.</p>
<div id="error" role="alert"></div><div class="grid"><section class="card"><h2>Solicitação</h2>
<label for="project">Projeto e Environment autorizado</label><select id="project"></select><small id="target"></small>
<label for="draft">Rascunho pronto</label><select id="draft"></select><small id="objective"></small>
<label for="path">Arquivo autorizado</label><select id="path"></select><button id="prepare" disabled>Preparar revisão</button>
<p id="configuration">Carregando configuração…</p><small>Somente free · até 6 chamadas · 512 tokens de saída/chamada · 90 segundos. Sem fallback pago.</small>
</section><section class="card"><h2>Execuções salvas</h2><select id="history" aria-label="Execuções salvas"><option value="">Selecione uma execução</option></select><button id="refresh">Atualizar resultados</button><p>Abrir ou atualizar uma execução apenas consulta o resultado. Não inicia outra tentativa.</p></section></div>
<section id="execution" class="card" hidden><h2>Progresso e resultado</h2><p id="status" class="status" role="status" aria-live="polite"></p><small id="identity"></small><p id="request"></p><small id="scope"></small><p id="model"></p><p id="block"></p>
<details id="review"><summary>Arquivo original e hash de aprovação</summary><small id="hash"></small><pre id="source"></pre></details>
<div id="approval"><label><input type="checkbox" id="consent">Autorizo uma tentativa limitada neste arquivo e Environment.</label><button id="approve" disabled>Autorizar edição com IA gratuita</button></div>
<h2>Evidências</h2><pre id="evidence"></pre><details id="artifact"><summary>Código resultante salvo</summary><small id="artifactHash"></small><pre id="code"></pre></details>
<small>A análise Luau é estática. PASS não comprova comportamento nem execução no Roblox. Se o resultado for desconhecido, reconcilie antes de criar qualquer nova intenção.</small>
</section></main><script>
const $=id=>document.getElementById(id);let options, current, timer, preparing=false, approving=false;
const base='/v1/supervised';const terminal=new Set(['COMPLETED','FAILED','BLOCKED','UNKNOWN_OUTCOME','CANCELLED']);
async function api(path,body,key){const controller=new AbortController(),t=setTimeout(()=>controller.abort(),12000);try{const r=await fetch(base+path,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',signal:controller.signal,headers:body?{'Content-Type':'application/json','X-AMODEX-Action':'supervised-v1',...(key?{'Idempotency-Key':key}:{})}:{},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.detail?.code||'REQUEST_BLOCKED');return d}finally{clearTimeout(t)}}
function error(e){$('error').textContent=e.name==='AbortError'?'Resposta não confirmada. Consulte a execução salva; não inicie outra tentativa.':e.message}
function option(select,value,text){const el=document.createElement('option');el.value=value;el.textContent=text;select.append(el)}
function selected(){return options.projects.find(p=>p.project_id===$('project').value)}
function selection(){const p=selected();$('path').replaceChildren();$('draft').replaceChildren();if(p){p.paths.forEach(x=>option($('path'),x,x));options.drafts.filter(d=>d.project_id===p.project_id).forEach(d=>option($('draft'),d.draft_id,d.title));$('target').textContent=`Environment ${p.environment_id} · Universe ${p.universe_id} · Place ${p.place_id}`}$('prepare').disabled=!p||!$('draft').value;draftSelection()}
function draftSelection(){$('objective').textContent=options?.drafts.find(d=>d.draft_id===$('draft').value)?.objective||'Crie e marque um rascunho como pronto no Workspace.'}
function display(d){current=d;localStorage.setItem('amodex.supervised.execution',d.execution_id);$('execution').hidden=false;$('status').textContent=d.status+' · '+d.phase;$('identity').textContent=`Run ${d.run_id} · Task ${d.task_id}`;$('request').textContent=d.objective;$('scope').textContent=`Environment ${d.environment_id} · ${d.path}`;$('model').textContent=d.route?`${d.route.provider} / ${d.route.model} · ${d.route.cost_class} · ${d.route.real_inference?'resposta de modelo recebida':'inferência ainda não confirmada'}`:'Modelo gratuito ainda não admitido';$('block').textContent=d.error_code||'';$('source').textContent=d.source;$('hash').textContent=d.source_sha256;$('approval').hidden=d.status!=='AWAITING_APPROVAL';$('approve').disabled=!$('consent').checked||approving;$('artifact').hidden=!d.artifact;$('code').textContent=d.artifact?.source||'';$('artifactHash').textContent=d.artifact?.sha256||'';$('evidence').textContent=JSON.stringify({local_validation:d.local_validation,calls:d.calls,tools:d.events},null,2);clearTimeout(timer);if(!terminal.has(d.status)&&d.status!=='AWAITING_APPROVAL')timer=setTimeout(()=>load(d.execution_id),1500)}
async function load(id){try{display(await api('/executions/'+id))}catch(e){error(e);timer=setTimeout(()=>load(id),5000)}}
async function history(){try{const d=await api('/executions');$('history').replaceChildren();option($('history'),'','Selecione uma execução');d.executions.forEach(x=>option($('history'),x.execution_id,`${x.status} · ${x.path} · ${x.execution_id.slice(-6)}`))}catch(e){error(e)}}
$('project').onchange=selection;$('draft').onchange=draftSelection;$('consent').onchange=()=>{$('approve').disabled=!$('consent').checked||approving};$('history').onchange=()=>{$('consent').checked=false;if($('history').value)load($('history').value)};
$('prepare').onclick=async()=>{if(preparing)return;preparing=true;$('prepare').disabled=true;$('error').textContent='';const body={draft_id:$('draft').value,project_id:$('project').value,path:$('path').value};const fingerprint=JSON.stringify(body);let pending;try{pending=JSON.parse(localStorage.getItem('amodex.supervised.intent')||'null')}catch{}if(!pending||pending.fingerprint!==fingerprint)pending={fingerprint,key:crypto.randomUUID()};localStorage.setItem('amodex.supervised.intent',JSON.stringify(pending));try{display(await api('/executions',body,pending.key));$('consent').checked=false;$('approve').disabled=true;$('review').open=true;await history()}catch(e){error(e)}finally{preparing=false;$('prepare').disabled=false}};
$('approve').onclick=async()=>{if(!current||approving||!$('consent').checked)return;approving=true;$('approve').disabled=true;const id=current.execution_id;try{display(await api('/executions/'+id+'/approve',{source_sha256:current.source_sha256}))}catch(e){error(e);await load(id)}finally{approving=false;$('consent').checked=false;await history()}};
$('refresh').onclick=async()=>{await history();if(current)await load(current.execution_id)};
(async()=>{try{options=await api('/options');options.projects.forEach(p=>option($('project'),p.project_id,p.project_id));selection();$('configuration').textContent=options.code||'Revisão obrigatória antes de qualquer inferência.';if(options.ready){await history();const id=localStorage.getItem('amodex.supervised.execution');if(id)await load(id)}}catch(e){error(e)}})();
</script></body></html>'''
